import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Platform is agnostic of language-specific plugins","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0002-platform-is-agnostic.md","filePath":"vendored/handl/project/adrs/0002-platform-is-agnostic.md"}`),a={name:`handl/project/adrs/0002-platform-is-agnostic.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="platform-is-agnostic-of-language-specific-plugins" tabindex="-1">Platform is agnostic of language-specific plugins <a class="header-anchor" href="#platform-is-agnostic-of-language-specific-plugins" aria-label="Permalink to “Platform is agnostic of language-specific plugins”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>handl-platform</code> is intended to be the generic host for the HAndL language toolchain: it defines the <code>Plugin</code> trait, <code>Host</code> coordination, capability resolution, and boundaries. Language-specific concerns — parsing, AST nodes, grammar rules, typechecking, formatting, linting, evaluation, and the VM — should be supplied as plugins.</p><p>Currently <code>crates/platform</code> directly depends on several non-platform crates:</p><ul><li><code>handl-plugin-vm</code> — re-exported as <code>Vm</code>.</li><li><code>handl-plugin-vm-values-json</code> — used by the value layer.</li><li><code>handl-kit-type</code> — re-exported for <code>Term</code>/<code>Value</code> primitives and <code>typecheck</code>.</li></ul><p>This couples the platform to a specific language (HAndL) and its type system. If another language wants to use the same host, it must either pull in the HAndL parser/typechecker/VM or live with unused dependencies and conflicting assumptions.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>handl-platform</code> must not depend on any language-specific crate. It may only depend on:</p><ol><li>The <code>plugin-lib-*</code> crates that define the <code>Plugin</code> contract and any shared, language-neutral primitives.</li><li>Utility crates for serialization, collections, etc. that have no language-specific knowledge.</li></ol><p>All of the following must be loaded as plugins through the <code>Plugin</code> system, not compiled into the platform:</p><ul><li><code>plugin-ast-*</code> (AST node plugins)</li><li><code>plugin-parser</code> (parser)</li><li><code>plugin-grammar-*</code> (grammar rules)</li><li><code>plugin-typecheck-core</code> (typechecking)</li><li><code>plugin-runtime-*</code> (runtime rules)</li><li><code>plugin-vm-*</code> and <code>plugin-vm-values-*</code> (VM and value representations)</li><li><code>plugin-eval-*</code> (eval rules)</li><li><code>plugin-fmt-*</code>, <code>plugin-lint-*</code>, <code>plugin-diag-*</code> (formatting, linting, diagnostics)</li></ul><p>The platform may keep shared, minimal types such as <code>Value</code>, <code>Term</code>, <code>Env</code>, and <code>CapabilityId</code> that plugins can build on. These should live in a dedicated, language-neutral crate (e.g. <code>plugin-lib-vm-values</code> or <code>lib-vm-values</code>) that the platform and all language plugins share.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>crates/platform</code> drops direct dependencies on <code>handl-plugin-vm</code>, <code>handl-plugin-vm-values-json</code>, <code>handl-kit-type</code>, <code>handl-kit-type-schema-json</code>, and all <code>plugin-ast-*</code> / <code>plugin-grammar-*</code> / <code>plugin-runtime-*</code> crates.</li><li><code>platform/src/value.rs</code> must stop re-exporting <code>handl-kit-type</code> primitives and instead expose platform-neutral <code>Value</code>/<code>Term</code> types, or re-export from a new <code>lib-vm-values</code> crate.</li><li><code>platform/src/lib.rs</code> must stop re-exporting <code>Vm</code> from <code>handl-plugin-vm</code>; the VM becomes a plugin that the host loads.</li><li>The existing <code>kit-*</code> and <code>plugin-*</code> crates become consumers of the platform instead of being compiled into it.</li><li>A new language can be supported by writing a different set of <code>plugin-*</code> crates and loading them into the same host.</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>accepted</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};